//! 📇️ One registered definition owns the original declaration graph; mounted registries retain only its shared lease and ordinals.
use super::*;
use std::{sync::Arc,mem::{ManuallyDrop,size_of}};
use semio_framework_value::{ValueError,ValueRefusalKind,retirement::RetireOwned};
use semio_framework_value_persistent::list::PagedList;
const ROW_LIMIT:usize=isize::MAX as usize;
/// 🧾️ Reference declarations keep their own value; native declarations expose one authenticated original shared source.
pub enum RegisteredAppDefinition{Reference(AppDefinition),Original(OriginalAppDefinition)}
impl RegisteredAppDefinition{
 pub fn declared(mut definition:AppDefinition,native:bool)->Self{if !native{return Self::Reference(definition)}for action in semio_framework::interaction_action_definitions(&definition){if !definition.actions.iter().chain(definition.window_kinds.iter().flat_map(|w|w.actions.iter())).any(|row|row.id==action.id){definition.actions.push(action)}}Self::Original(OriginalAppDefinition::new(definition))}
 pub fn commit_producer(&mut self){if let Self::Original(owner)=self{owner.committed=true;}}
 pub fn reference_mut(&mut self)->Option<&mut AppDefinition>{match self{Self::Reference(value)=>Some(value),Self::Original(_)=>None}}
 pub fn original_source(&self)->Option<RegisteredDefinitionSource<'_>>{match self{Self::Original(owner)=>owner.source.as_ref().map(|original|RegisteredDefinitionSource{original,committed:owner.committed}),Self::Reference(_)=>None}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{match self{Self::Original(owner)=>owner.close_demands(body),Self::Reference(_)=>Ok(Default::default())}}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{match self{Self::Original(owner)=>owner.close_step(grant),Self::Reference(_)=>Ok(RetainedCloneStep::Complete(Default::default()))}}
 pub fn terminal_is_empty(&self)->bool{match self{Self::Original(owner)=>owner.terminal_is_empty(),Self::Reference(_)=>true}}
}
impl From<AppDefinition> for RegisteredAppDefinition{fn from(value:AppDefinition)->Self{Self::Reference(value)}}
impl std::ops::Deref for RegisteredAppDefinition{type Target=AppDefinition;fn deref(&self)->&AppDefinition{match self{Self::Reference(value)=>value,Self::Original(owner)=>owner.source.as_ref().expect("registered source has entered final closure")}}}
/// 🎟️ Only the actual declaration source can lend this native registry capability.
#[derive(Clone,Copy)]
pub struct RegisteredDefinitionSource<'a>{original:&'a Arc<AppDefinition>,committed:bool}
impl std::ops::Deref for RegisteredDefinitionSource<'_>{type Target=AppDefinition;fn deref(&self)->&AppDefinition{self.original}}

/// 🏛️ Declaration commit produces this original immutable source before any mounted request exists.
pub struct OriginalAppDefinition{source:ManuallyDrop<Option<Arc<AppDefinition>>>,retirement:Option<Box<dyn semio_framework_value::ErasedSnapshotRetirement>>,committed:bool}
impl OriginalAppDefinition{
 pub fn new(value:AppDefinition)->Self{Self{source:ManuallyDrop::new(Some(Arc::new(value))),retirement:None,committed:false}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=self.retirement.as_ref(){return dsl::os_store::snapshot_read::artifact_retirement_box_demands(owner,body)}if let Some(source)=self.source.as_ref(){if Arc::strong_count(source)!=1{return Ok(RetirementDemand{depth:1,..Default::default()})}return dsl::os_store::snapshot_read::artifact_retirement_owned_birth_demands(&*self.source)}Ok(Default::default())}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.retirement.is_some(){return dsl::os_store::snapshot_read::artifact_retirement_box_close_step(&mut self.retirement,grant)}if self.source.as_ref().is_some_and(|source|Arc::strong_count(source)!=1){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.source.is_some(){return dsl::os_store::snapshot_read::artifact_retirement_admit_owned(&mut self.source,&mut self.retirement,grant)}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.retirement.is_none()}
}
impl Drop for OriginalAppDefinition{fn drop(&mut self){if !self.committed&&self.retirement.is_none()&&self.source.as_ref().is_none_or(|owner|Arc::strong_count(owner)==1){drop(self.source.take());return}assert!(std::thread::panicking()||self.terminal_is_empty(),"committed native definition requires original alias return and typed graph closure")}}
#[derive(Clone,Copy,semio_framework_value::RetireOwned)]
struct Ordinal{kind:u8,rank:usize,child:usize,hash:u64}
fn hash(value:&str)->u64{value.bytes().fold(0xcbf29ce484222325,|value,byte|(value^u64::from(byte)).wrapping_mul(0x100000001b3))}
/// 🪢️ This mounted alias owns no Action, Command, ToolRun or localized label copy.
pub(super) struct NativeRegistry{source:ManuallyDrop<Option<Arc<AppDefinition>>>,retirement:Option<Box<dyn semio_framework_value::ErasedSnapshotRetirement>>,ordinals:PagedList<Ordinal,ROW_LIMIT>,index_close:semio_framework_value::retained_clone::RetainedCloneClose,phase:u8,rank:usize,child:usize,hash_offset:usize,hash_state:u64,pub(super) ready:bool,closing:bool}
impl NativeRegistry{
 pub(super) fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Self>()+size_of::<Arc<AppDefinition>>(),depth:1,..Default::default()}}
 pub(super) fn admit(source:RegisteredDefinitionSource<'_>,grant:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,ValueError>{if !source.committed{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"native registry requires its committed declaration producer"))}let d=Self::birth_demands();if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d){return Ok(None)}Ok(Some((Self{source:ManuallyDrop::new(Some(Arc::clone(source.original))),retirement:None,ordinals:Default::default(),index_close:Default::default(),phase:0,rank:0,child:0,hash_offset:0,hash_state:0xcbf29ce484222325,ready:false,closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 pub(super) fn definition(&self)->&AppDefinition{self.source.as_ref().expect("native registry source remains live")}
 fn current(&self)->Option<(&str,usize,usize)>{let d=self.definition();match self.phase{0=>d.actions.get(self.rank).map(|r|(r.id.as_str(),self.rank,0)),1=>d.window_kinds.iter().nth(self.rank).and_then(|r|r.actions.get(self.child)).map(|r|(r.id.as_str(),self.rank,self.child)),2=>d.commands.get(self.rank).map(|r|(r.id.as_str(),self.rank,0)),3=>d.modes.iter().nth(self.rank).and_then(|r|r.commands.get(self.child)).map(|r|(r.id.as_str(),self.rank,self.child)),4=>d.tools.get(self.rank).map(|r|(r.id.as_str(),self.rank,0)),5=>d.utilities.get(self.rank).map(|r|(r.id.as_str(),self.rank,0)),6=>d.interactions.get(self.rank).map(|r|(r.id.as_str(),self.rank,0)),_=>None}}
 pub(super) fn demands(&self)->Result<RetirementDemand,ValueError>{
  if self.ready{return Ok(Default::default())}
  if let Some((id,_,_))=self.current(){if self.hash_offset<id.len(){return Ok(RetirementDemand{copy_bytes:1+size_of::<usize>()+size_of::<u64>(),depth:1,..Default::default()})}if !self.ordinals.has_reserved_slot(){return Ok(RetirementDemand{copy_bytes:self.ordinals.next_reserve_copy_byte_demand().map_err(ValueError::from)?,capacity_bytes:self.ordinals.next_allocation_bytes().map_err(ValueError::from)?,depth:self.ordinals.next_reserve_depth_demand().map_err(ValueError::from)?,..Default::default()})}}
  Ok(RetirementDemand{copy_bytes:size_of::<Ordinal>()+4*size_of::<usize>()+size_of::<u64>()+2,depth:1,..Default::default()})
 }
 pub(super) fn advance(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
  if self.closing{return Err(invalid("native registry is closing"))}if self.ready{return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.demands()?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}
  let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};
  if let Some((id,rank,child))=self.current(){if let Some(byte)=id.as_bytes().get(self.hash_offset).copied(){self.hash_state=(self.hash_state^u64::from(byte)).wrapping_mul(0x100000001b3);self.hash_offset+=1;return Ok(RetainedCloneStep::Progress(p))}let entry=Ordinal{kind:self.phase,rank,child,hash:self.hash_state};if !self.ordinals.has_reserved_slot(){let progress=self.ordinals.reserve_one_funded(grant).map_err(|error|ValueError::literal(ValueRefusalKind::OwnershipLimit,error.reason).with_retained_progress(RetainedCloneProgress{retained_capacity_bytes:error.allocated_bytes,..Default::default()}))?;return Ok(RetainedCloneStep::Progress(progress))}self.ordinals.push_reserved(entry).map_err(|_|invalid("native registry ordinal lost its reserved page"))?;if self.phase==1||self.phase==3{self.child+=1}else{self.rank+=1}}else if self.phase==1&&self.rank+1<self.definition().window_kinds.len()||self.phase==3&&self.rank+1<self.definition().modes.len(){self.rank+=1;self.child=0}else{self.phase+=1;self.rank=0;self.child=0;if self.phase==7{self.ready=true}}
  self.hash_offset=0;self.hash_state=0xcbf29ce484222325;Ok(if self.ready{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})
 }
 pub(super) fn action(&self,id:&str)->Option<&ActionDefinition>{let h=hash(id);let d=self.definition();[1,0].into_iter().flat_map(|kind|self.ordinals.iter().filter(move|r|r.hash==h&&r.kind==kind)).find_map(|r|{let row=if r.kind==0{d.actions.get(r.rank)}else{d.window_kinds.iter().nth(r.rank)?.actions.get(r.child)}?;(row.id==id).then_some(row)})}
 pub(super) fn window_action(&self,window:&str,id:&str)->Option<&ActionDefinition>{let d=self.definition();let w=d.window_kinds.iter().find(|w|w.id==window)?;w.actions.iter().find(|a|a.id==id).or_else(||{if d.window_kinds.iter().any(|w|w.actions.iter().any(|a|a.id==id)){None}else{d.actions.iter().find(|a|a.id==id)}})}
 pub(super) fn command(&self,id:&str)->Option<&CommandDefinition>{let h=hash(id);let d=self.definition();self.ordinals.iter().filter(|r|r.hash==h&&(r.kind==2||r.kind==3)).find_map(|r|{let row=if r.kind==2{d.commands.get(r.rank)}else{d.modes.iter().nth(r.rank)?.commands.get(r.child)}?;(row.id==id).then_some(row)})}
 pub(super) fn tool_run(&self,id:&str)->Option<(&LocalizedLabel,&semio_framework_tool_run::ToolRunDefinition)>{let h=hash(id);let d=self.definition();self.ordinals.iter().filter(|r|r.hash==h&&(r.kind==4||r.kind==5)).find_map(|r|if r.kind==4{let row=d.tools.get(r.rank)?;(row.id==id).then(||row.run.as_ref().map(|run|(&row.label,run))).flatten()}else{let row=d.utilities.get(r.rank)?;(row.id==id).then(||row.run.as_ref().map(|run|(&row.label,run))).flatten()})}
 pub(super) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(RetirementDemand{copy_bytes:1,depth:1,..Default::default()})}if !self.ordinals.terminal_is_empty()||!self.index_close.is_empty(){return self.index_close.next_owner_demands::<PagedList<Ordinal,ROW_LIMIT>>(!self.ordinals.terminal_is_empty(),&None,body)}if let Some(owner)=self.retirement.as_ref(){return dsl::os_store::snapshot_read::artifact_retirement_box_demands(owner,body)}if self.source.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<Arc<AppDefinition>>>(),capacity_bytes:semio_framework_value::retirement::arc_custody::shared_retirement_birth_bytes::<AppDefinition>(),depth:1,..Default::default()})}Ok(Default::default())}
 pub(super) fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demands(grant.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.closing{self.closing=true;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()}))}if !self.ordinals.terminal_is_empty()||!self.index_close.is_empty(){let mut source=None;if !self.ordinals.terminal_is_empty(){source=Some(std::mem::take(&mut self.ordinals))}if let Some(step)=self.index_close.begin_granted(&mut source,grant)?{if let Some(owner)=source{self.ordinals=owner}return Ok(step)}return self.index_close.step_granted(grant)}if self.retirement.is_some(){return dsl::os_store::snapshot_read::artifact_retirement_box_close_step(&mut self.retirement,grant)}if let Some(source)=self.source.take(){match semio_framework_value::retirement::arc_custody::admit_shared_retirement(source,grant,true){Ok((owner,mut p))=>{self.retirement=Some(owner);p.copied_bytes=d.copy_bytes;return Ok(RetainedCloneStep::Progress(p))}Err((error,source))=>{*self.source=Some(source);return Err(error)}}}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub(super) fn terminal_is_empty(&self)->bool{self.closing&&self.source.is_none()&&self.retirement.is_none()&&self.ordinals.terminal_is_empty()&&self.index_close.is_empty()}
}
impl Drop for NativeRegistry{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native action registry requires original ordinal and source alias closure")}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
